var tagPage = Number(infoMap['标签页'] || 1);
if (!isFinite(tagPage) || tagPage < 1 || Math.floor(tagPage) !== tagPage) tagPage = 1;
var rows = [];
var tagUrl = String(source.getKey()) + '/tag?sort=pop&p=' + tagPage;
var response = java.connect(tagUrl + ',' + JSON.stringify({webView:true}));
var doc = org.jsoup.Jsoup.parse(String(response.body()));
var links = doc.select("div.col > a[href^='/tag/']");
for (var i = 0; i < links.size(); i++) {
    var a = links.get(i);
    rows.push({ title: String(a.text()), url: String(a.attr('href')) + "?sort={{({'最新':'date','阅读量':'view','收藏数':'like','字数':'char'})[infoMap['文章排序']]||'date'}}&p={{page}}" });
}
if (tagPage > 1) rows.push({ title: '上一页标签', type: 'button', action: "infoMap['标签页']='" + (tagPage - 1) + "';java.refreshExplore()" });
if (!doc.select("button[aria-label='后一页']:not([disabled])").isEmpty()) {
    rows.push({ title: '下一页标签', type: 'button', action: "infoMap['标签页']='" + (tagPage + 1) + "';java.refreshExplore()" });
}
JSON.stringify(rows);
